    { term: "Intra-continental relations", def: "Relations that occur within one continent, such as contacts among African peoples." },
    { term: "Inter-continental relations", def: "Relations that occur between two or more continents, such as Africa's trade with Asia and Europe." },
    { term: "Trans-Atlantic slave trade", def: "The slave trade that opened after Afro-European contact during the era of exploration." }
