    { term: "Super-family", def: "One of the four large groups of African languages: Congo-Kordofanian, Afro-Asiatic, Nilo-Saharan and Khoisan." },
    { term: "Mamluk", def: "Soldiers of Turkish origin who ruled Egypt from 1250 to 1517." },
    { term: "Trans-Saharan trade", def: "The caravan trade across the Sahara that carried gold and salt and linked Africa to the wider world." },
    { term: "Mansa Musa", def: "The greatest king of Mali (1312-1337), remembered for his pilgrimage to Mecca." },
    { term: "Mwene Mutapa", def: "The empire founded after 1450 AD by the Rozwi clan kings of the Shona." },
    { term: "Swahili city-states", def: "Wealthy Muslim trading ports of the East African coast, such as Kilwa." },
    { term: "Cultural diffusion", def: "The blending of traditions from different peoples, as in Swahili civilization." },
    { term: "Trans-Atlantic slave trade", def: "The slave trade that opened after Afro-European contact during the era of exploration." }
